<?php declare(strict_types=1);namespace App\Services;use App\Core\DB;use App\Core\I18n;use App\Core\Mailer;use App\Models\AuditLog;use App\Models\Coupon;use App\Models\License;use App\Models\Order;use App\Models\Plan;use App\Models\User;final class OrderService{public static function create(array $q,array $f,string $A,?array $o=null,string $y='new',?int $n=null):array{$C=Plan::price($f,$A);$S=$o?CouponService::discount($o,$C):0;$M=InvoiceService::compute($C,$S,(string)$q['country'],$q['vat_number']);$k=User::billingSnapshot($q);$k['lang']=$q['lang']?:I18n::locale();$g=Order::create(['user_id'=>(int)$q['id'],'plan_id'=>(int)$f['id'],'license_id'=>$n,'period'=>$A==='year'?'year':'month','status'=>'pending','kind'=>$y,'currency'=>$f['currency']?:'EUR','subtotal'=>$M['subtotal'],'discount'=>$M['discount'],'tax_rate'=>$M['tax_rate'],'tax'=>$M['tax'],'total'=>$M['total'],'reverse_charge'=>$M['reverse_charge']?1:0,'coupon_id'=>$o['id']??null,'coupon_code'=>$o['code']??null,'billing'=>$k,'payment_provider'=>StripeService::mode()]);AuditLog::log('order.create',(string)$g,['plan'=>$f['slug'],'period'=>$A,'total'=>$M['total']]);return Order::find($g);}public static function markPaid(array $e,string $i,?string $B=null):array{if($e['status']==='paid'){return $e;}return DB::transaction(function()use($e,$i,$B){$o=User::find((int)$e['user_id']);$V=Plan::find((int)$e['plan_id']);$t=$e['period']==='year'?12:1;if($e['kind']==='renewal'&&$e['license_id']){$a=LicenseService::extend(License::find((int)$e['license_id']),$t,(int)$e['id']);}elseif($e['kind']==='change'&&$e['license_id']){$a=LicenseService::changePlan(License::find((int)$e['license_id']),$V,$e['period'],(int)$e['id']);}else{$a=LicenseService::create((int)$o['id'],$V,$e['period'],(int)$e['id']);}Order::update((int)$e['id'],['status'=>'paid','paid_at'=>now(),'payment_provider'=>$i,'payment_ref'=>$B,'license_id'=>(int)$a['id']]);if($e['coupon_id']){$s=Coupon::find((int)$e['coupon_id']);if($s){CouponService::consume($s);}}$e=Order::find((int)$e['id']);$m=InvoiceService::createForOrder($e);AuditLog::log('order.paid',(string)$e['id'],['provider'=>$i,'ref'=>$B,'license'=>$a['license_key']],(int)$o['id']);try{$h=new Mailer();$I=$o['lang']?:'fr';$h->sendTemplate($o['email'],'order_confirmation',['user'=>$o,'order'=>$e,'license'=>$a,'plan'=>$V,'invoice'=>$m],$I,$o['name']);$h->sendTemplate($o['email'],'invoice',['user'=>$o,'order'=>$e,'invoice'=>$m],$I,$o['name']);}catch(\Throwable $A){tp_log('mail','Commande '.$e['id'].' : '.$A->getMessage());}return $e;});}public static function label(array $W,array $S,?string $a=null):string{return'ToutPVR '.I18n::pick($S['name'],$a).' — '.I18n::t('period.'.$W['period'],[],$a);}}